-- Ethiopia administrative level 2 (Zones)
-- Source: ETH_Zones.shp
-- Records: 101

DROP TABLE IF EXISTS "eth_zones" CASCADE;

CREATE TABLE "eth_zones" (
    "OBJECTID" INTEGER,
    "admin2Name" TEXT,
    "admin2Pcod" TEXT,
    "admin2RefN" TEXT,
    "admin2AltN" TEXT,
    "admin2Al_1" TEXT,
    "admin1Name" TEXT,
    "admin1Pcod" TEXT,
    "admin0Name" TEXT,
    "admin0Pcod" TEXT,
    "date" DATE,
    "validOn" DATE,
    "validTo" DATE,
    "Lat" DOUBLE PRECISION,
    "Long" DOUBLE PRECISION,
    "Shape_Leng" DOUBLE PRECISION,
    "Shape_Area" DOUBLE PRECISION,
    geom geometry(MultiPolygon, 4326) NOT NULL
);

COMMENT ON TABLE "eth_zones" IS 'Ethiopia administrative level 2 (Zones)';


CREATE INDEX "eth_zones_geom_idx" ON "eth_zones" USING GIST (geom);
